<script setup>import {useForm} from '@inertiajs/vue3'; import {computed} from 'vue'; import AppLayout from '../../../Layouts/AppLayout.vue'; const props=defineProps({accounts:Array,costCenters:Array,documentTypes:Object,endpoints:Object}); const line=()=>({account_id:'',cost_center_id:'',detail:'',debit:'',credit:''}); const form=useForm({date:new Date().toISOString().slice(0,10),concept:'',reference:'',document_type:'',document_number:'',counterparty_name:'',counterparty_ruc:'',notes:'',lines:[line(),line()]}); const debit=computed(()=>form.lines.reduce((n,l)=>n+Number(l.debit||0),0)); const credit=computed(()=>form.lines.reduce((n,l)=>n+Number(l.credit||0),0));</script>
<template><AppLayout title="Nuevo asiento" eyebrow="Contabilidad trazable" description="Registra el soporte fiscal; el movimiento se guarda en borrador antes de contabilizarse."><form class="space-y-4" @submit.prevent="form.post(endpoints.store)"><section class="card p-5"><div class="grid gap-4 md:grid-cols-2 xl:grid-cols-4"><label class="field-label">Fecha<input v-model="form.date" type="date" class="control"></label><label class="field-label xl:col-span-3">Concepto<input v-model="form.concept" class="control"></label><label class="field-label">Tipo de soporte<select v-model="form.document_type" class="control"><option value="">Sin clasificar</option><option v-for="(label,value) in documentTypes" :key="value" :value="value">{{label}}</option></select></label><label class="field-label">Número de documento<input v-model="form.document_number" class="control" placeholder="Serie y consecutivo"></label><label class="field-label">Contraparte<input v-model="form.counterparty_name" class="control" placeholder="Nombre o razón social"></label><label class="field-label">RUC / identificación<input v-model="form.counterparty_ruc" class="control" placeholder="Según documento soporte"></label><label class="field-label">Referencia interna<input v-model="form.reference" class="control"></label><label class="field-label md:col-span-2 xl:col-span-3">Notas<input v-model="form.notes" class="control"></label></div></section><section class="card overflow-hidden"><div class="section-heading flex justify-between"><div><h2 class="font-semibold">Líneas de doble partida</h2><p class="text-xs text-slate-400">Cada línea admite cuenta, centro de costo y detalle.</p></div><button type="button" class="btn-soft" @click="form.lines.push(line())">Agregar línea</button></div><div v-for="(row,i) in form.lines" :key="i" class="grid gap-3 border-b p-4 lg:grid-cols-[1.2fr_.8fr_1fr_130px_130px_auto]"><select v-model="row.account_id" class="control"><option value="">Cuenta</option><option v-for="account in accounts" :key="account.id" :value="account.id">{{account.code}} · {{account.name}}</option></select><select v-model="row.cost_center_id" class="control"><option value="">Sin centro de costo</option><option v-for="center in costCenters" :key="center.id" :value="center.id">{{center.code}} · {{center.name}}</option></select><input v-model="row.detail" class="control" placeholder="Detalle"><input v-model="row.debit" type="number" step=".01" min="0" class="control" placeholder="Debe"><input v-model="row.credit" type="number" step=".01" min="0" class="control" placeholder="Haber"><button v-if="form.lines.length>2" type="button" class="text-rose-600" aria-label="Quitar línea" @click="form.lines.splice(i,1)">×</button></div><div class="flex flex-wrap justify-end gap-6 p-4 text-sm"><span>Debe: C$ {{debit.toFixed(2)}}</span><span>Haber: C$ {{credit.toFixed(2)}}</span><strong :class="debit===credit&&debit>0?'text-emerald-700':'text-rose-600'">Diferencia: {{(debit-credit).toFixed(2)}}</strong></div></section><p v-if="Object.keys(form.errors).length" class="text-xs text-rose-600">{{Object.values(form.errors).join(' · ')}}</p><button class="btn-primary" :disabled="form.processing">Guardar borrador</button></form></AppLayout></template>
